-- 0033: every table says what it is for (visible in psql \d+ and the generated database/SCHEMA.md), and the promotion funnel gains "served".
-- Comments only plus one widened CHECK; no data moves and nothing is dropped.

COMMENT ON TABLE users IS 'One row per person who has ever signed in: email, display name and role (user or admin). The identity every other table points at.';
COMMENT ON TABLE oauth_accounts IS 'Connected identities: an ownership dimension, not a user.';
COMMENT ON TABLE devices IS 'A machine a person has used the desktop app on: platform, app version and last seen.';
COMMENT ON TABLE workspaces IS 'A folder or project a person works in, as the app reports it (a name and id, never its files).';
COMMENT ON TABLE sessions IS 'One agent conversation inside a workspace: when it started, ended and which model ran it. Content is not stored here.';
COMMENT ON TABLE session_events IS 'Append-only. event_id = idempotency key; sequence is gap-free per session. Stage B partitions this table by created_at (measured need, not up front).';
COMMENT ON TABLE agent_runs IS 'One run of the agent inside a session: timing, outcome and token counts.';
COMMENT ON TABLE document_revisions IS 'Metadata of document saves the sync API accepted (revision number, size, hash). Never the document bytes.';
COMMENT ON TABLE memory_references IS 'Pointers to agent memory items a person synced (id and kind only, never the memory text).';
COMMENT ON TABLE sync_cursors IS 'How far each device has synced each stream, so a device resumes where it stopped.';
COMMENT ON TABLE admin_audit IS 'Every admin view of a user, every admin action, every admin SQL query.';
COMMENT ON TABLE device_metrics IS 'Device metrics for System health: timings and gauges a device reports (event write latency, checkpoint time, retrieval p95, extraction-queue lag, outbox depth). Numbers only, never content. Kept 30 days.';
COMMENT ON TABLE device_tokens IS 'Long-lived device sign-in tokens (hash only, never the token). The desktop app signs in through Keycloak and the API swaps that for a device token so the app keeps syncing; revoking a row signs that device out.';
COMMENT ON TABLE auth_accounts IS 'One row per linked sign-in method (Google, Microsoft, email+password). Provider tokens and the password hash live here, so only the admin role can read it: not the sync API, not the SQL runner.';
COMMENT ON TABLE auth_sessions IS 'Browser sessions of the sign-in pages and the web admin. Not desktop sessions (device_tokens).';
COMMENT ON TABLE auth_verifications IS 'Email links now, phone codes later.';
COMMENT ON TABLE plans IS 'The plans on offer (Free, Pro, Max 5x, Max 20x): entitlements and limits live here, not in code.';
COMMENT ON TABLE subscriptions IS 'Which plan each person is on now, its status and renewal date.';
COMMENT ON TABLE entitlements IS 'Per-user overrides of what a plan allows (a feature flag, a higher limit), optionally temporary.';
COMMENT ON TABLE credit_ledger IS 'Append-only record of every credit grant, spend, refund and expiry. A balance is the sum of this table, never a stored number.';
COMMENT ON TABLE credit_reservations IS 'Credits held while a managed-compute call is running, released or settled when it ends.';
COMMENT ON TABLE usage_events IS 'One row per managed-compute call: who, which model, tokens in and out, credits charged. No prompts or answers.';
COMMENT ON TABLE api_keys IS 'Keys a user can use to call managed compute from their own tools. Only the hash is stored.';
COMMENT ON TABLE coupons IS 'Coupon codes (stored hashed) with their credit or plan effect, limits and expiry.';
COMMENT ON TABLE coupon_redemptions IS 'Who redeemed which coupon and when; a person can redeem a code once.';
COMMENT ON TABLE admin_roles IS 'The role each administrator holds (owner, admin, support, billing, ...); permissions come from the role, never from a client claim.';
COMMENT ON TABLE usage_consent IS 'Whether a person agreed to share usage (off by default). Run telemetry is written only while shared is true, and only allow-listed, non-free-text fields.';
COMMENT ON TABLE run_steps IS 'Opt-in telemetry: the tool steps of an agent run (tool name, duration, outcome). Written only when the person shares usage.';
COMMENT ON TABLE verification_results IS 'Opt-in telemetry: whether an agent run passed its own checks. Written only when the person shares usage.';
COMMENT ON TABLE feature_flags IS 'Feature flags the server enforces, with an optional plan or percentage rollout.';
COMMENT ON TABLE announcements IS 'Messages an administrator publishes to people in the app, with audience, schedule and severity.';
COMMENT ON TABLE announcement_reads IS 'Which person has read which announcement.';
COMMENT ON TABLE support_tickets IS 'Help requests opened by signed-in people, with status and the assigned administrator.';
COMMENT ON TABLE support_messages IS 'The replies on a support ticket, from the person and from administrators.';
COMMENT ON TABLE email_deliveries IS 'One row per announcement email per person, written only from the provider''s own answer (''sent'' with its message id, or ''failed'' with its error). The unique key makes re-sending an announcement skip everyone already emailed.';
COMMENT ON TABLE sign_in_events IS 'Every sign-in, as the server saw it: who, through what, from which app and machine and address.';
COMMENT ON TABLE plan_prices IS 'Price of each plan per currency and billing period, with the date it takes effect. INR first; changes add rows, they never edit history.';
COMMENT ON TABLE plan_change_events IS 'Append-only history of plan changes (who, from, to, why, when) for audit and support.';
COMMENT ON TABLE payment_orders IS 'A person''s intent to pay: plan, amount, currency and state. Becomes paid only after a provider settlement is verified, never from a browser callback.';
COMMENT ON TABLE payment_attempts IS 'Each try to pay an order with a provider: provider reference, state and failure reason.';
COMMENT ON TABLE payment_events IS 'Everything a provider told us, kept as received; (provider, delivery id) is unique so a replay changes nothing.';
COMMENT ON TABLE subscription_periods IS 'The dated periods a paid plan covers. A plan is active only inside a period created from a verified payment.';
COMMENT ON TABLE invoices IS 'The invoice issued for a settled order: number, amounts and tax lines.';
COMMENT ON TABLE access_requests IS 'A signed-in person who is not an administrator can ask for admin access; an administrator approves (choosing the admin role) or declines. Approving goes through the same role code as every other role change, so its guards (active account, last superadmin) apply. The request only records who asked, a short note, and what was decided and by whom.';
COMMENT ON TABLE admin_invites IS 'An administrator adds another administrator by email before that person has ever signed in. The invite waits; the first time the person signs in to the console with that VERIFIED email, they become an administrator with the chosen role (through the same guarded role code as every other change). An unverified email never claims an invite. Invites are used once and can be revoked.';
COMMENT ON TABLE marketplace_publishers IS 'People or teams allowed to publish to the marketplace, with their verification state.';
COMMENT ON TABLE marketplace_teams IS 'Organizations that share marketplace items and policies.';
COMMENT ON TABLE marketplace_team_members IS 'Who belongs to a marketplace team and in what role.';
COMMENT ON TABLE marketplace_listings IS 'A marketplace entry (skill, agent, template, bundle): name, type, publisher and state.';
COMMENT ON TABLE marketplace_artifacts IS 'The uploaded file behind a version: storage key, size and content hash.';
COMMENT ON TABLE marketplace_versions IS 'Each released version of a listing, with its changelog and approval state.';
COMMENT ON TABLE marketplace_dependencies IS 'Which listings and versions a version needs in order to run.';
COMMENT ON TABLE marketplace_submissions IS 'A publisher''s request to publish or update a listing, moving through review.';
COMMENT ON TABLE marketplace_reviews IS 'Ratings and written reviews people leave on a listing.';
COMMENT ON TABLE marketplace_favorites IS 'Listings a person has favorited.';
COMMENT ON TABLE marketplace_installs IS 'Which person has which listing version installed on which device.';
COMMENT ON TABLE marketplace_install_events IS 'Append-only audit trail. Deliberately no foreign keys: a cascade from users/listings would fire the append-only trigger and block erasure, and history must not be rewritten. user_id is therefore unvalidated text by design.';
COMMENT ON TABLE marketplace_usage_events IS 'Aggregate usage signals for listings (counts only, no content).';
COMMENT ON TABLE marketplace_collections IS 'Curated groups of listings shown on the marketplace.';
COMMENT ON TABLE marketplace_collection_items IS 'The listings inside a collection and their order.';
COMMENT ON TABLE marketplace_security_scans IS 'Results of the verifier''s security scan of an artifact: verdict and findings.';
COMMENT ON TABLE marketplace_reports IS 'Abuse or policy reports people file against a listing, and how they were handled.';
COMMENT ON TABLE marketplace_release_events IS 'Release / revocation history. Append-only, no foreign keys (same reasoning as install events).';
COMMENT ON TABLE marketplace_listing_counters IS 'Favorite and install counts are maintained by SECURITY DEFINER triggers into a table with no RLS, so they are right no matter whose rows the reader can see. Ratings are computed from review rows (a public-read policy covers visible listings).';
COMMENT ON TABLE marketplace_team_assignments IS 'Which team may use which listing, assigned by a team admin.';
COMMENT ON TABLE marketplace_policies IS 'Named rule sets a team applies to what its members may install.';
COMMENT ON TABLE marketplace_policy_rules IS 'The individual allow and deny rules inside a policy.';
COMMENT ON TABLE marketplace_type_policy IS 'Per listing type: whether verification and review are required before it is published.';
COMMENT ON TABLE marketplace_settings IS 'Which listing types require a passing verification before approved/published. DATA, not hardcoded: it starts empty and an operator turns a type on (UPDATE as the owner role) once its pipeline is registered, because enforcing it for a type that has no pipeline would make that type unpublishable. ao_app and ao_admin cannot write it.';
COMMENT ON TABLE marketplace_verifications IS 'The outcome of verifying an artifact (scan and compile), kept per version.';
COMMENT ON TABLE marketplace_team_audit IS 'Append-only trail of team administration actions in the marketplace.';
COMMENT ON TABLE marketplace_verify_jobs IS 'The queue the verification worker claims jobs from: one job per artifact version to scan and compile.';
COMMENT ON TABLE placements IS 'The surfaces the app can render. contract_version is what a client must support to be sent a creative made for it.';
COMMENT ON TABLE campaigns IS 'A house promotion: name, tier, schedule, priority, holdout percentage, frequency caps and optional feature flag.';
COMMENT ON TABLE campaign_targets IS 'Who a campaign is for. Every list null = everyone; a person must match every list that is set.';
COMMENT ON TABLE creatives IS 'The content of a promotion on one placement: headline, body, call to action, kind (image, clip, card) and contract version.';
COMMENT ON TABLE creative_media IS 'Media files in object storage: the uploaded source and the variants the worker made from it.';
COMMENT ON TABLE media_jobs IS 'The media worker''s queue (claimed with FOR UPDATE SKIP LOCKED, so several workers never take the same job).';
COMMENT ON TABLE promo_events IS 'What the app reported. event_id is generated by the app, so a retried batch is counted once. user_id is null for someone who has not agreed to share usage (usage_consent): their events still count in totals, but are not linked to them.';
COMMENT ON TABLE promo_exposure IS 'Frequency must hold for people who share no usage too, so delivery is also counted per person in a separate, minimal table the app cannot read others'' rows of. It records only when something was shown or dismissed, nothing else.';
COMMENT ON TABLE user_promo_prefs IS 'A person''s own choices. In-app promotions are on unless they switch them off; marketing email is off unless they switch it on.';
COMMENT ON TABLE releases IS 'A shipped app version and its staged rollout state.';
COMMENT ON TABLE release_rollouts IS 'Every change of a rollout stage, newest last: the history the release page shows and an auditor reads.';
COMMENT ON TABLE email_templates IS 'Campaign email templates (HTML and plain text); every one must carry the unsubscribe link.';
COMMENT ON TABLE campaign_emails IS 'One send of a campaign email to one person, with its delivery state.';
COMMENT ON TABLE webhook_events IS 'Each Resend webhook is processed once: its svix-id is recorded before it is applied, and a repeat is acknowledged and ignored.';
COMMENT ON TABLE service_status IS 'The current state of each service (up, degraded or down) with latency and when it was last checked. Coarse facts only; the public status page reads this.';
COMMENT ON TABLE status_checks IS 'One row per probe of one service by the prober (state, latency, time); service_status holds the latest state, this keeps the history behind the status page bars.';
COMMENT ON TABLE help_chunks IS 'The help assistant knowledge base: chunks of the platform documentation (never user data), each with an embedding stored as real[].';
COMMENT ON TABLE help_questions IS 'One row per question: who asked, a hash and the length of the question (not the text), what answered it, whether it helped. Rows with no sources or a "no" are the gaps in the documentation.';

-- Delivery funnel: "served" is the server saying it handed an item to a device, once a day per person, campaign and placement.
-- Next to "impression" (the app says it showed it) the admin can tell an ad that never left the server from one the app never drew.
ALTER TABLE promo_events DROP CONSTRAINT IF EXISTS promo_events_type_check;
ALTER TABLE promo_events ADD CONSTRAINT promo_events_type_check CHECK (type IN ('served', 'impression', 'view', 'click', 'dismiss', 'conversion', 'holdout'));
COMMENT ON COLUMN promo_events.type IS 'served = the server returned this campaign to a device; impression/view/click/dismiss/conversion = what the app reported; holdout = held back on purpose.';

-- Better Auth leftovers (migration 0006; Keycloak replaced Better Auth). Kept, unused, until the owner decides to drop them after the retirement window.
COMMENT ON TABLE jwks IS 'Retired (Better Auth): signing keys of the old sign-in service. Unused since the Keycloak cutover.';
COMMENT ON TABLE "twoFactor" IS 'Retired (Better Auth): two-factor secrets of the old sign-in service. Administrator MFA is Keycloak''s now.';
COMMENT ON TABLE "oauthClient" IS 'Retired (Better Auth): OAuth clients of the old sign-in service. Unused since the Keycloak cutover.';
COMMENT ON TABLE "oauthClientAssertion" IS 'Retired (Better Auth): client assertions of the old sign-in service.';
COMMENT ON TABLE "oauthClientResource" IS 'Retired (Better Auth): resources an old OAuth client may reach.';
COMMENT ON TABLE "oauthResource" IS 'Retired (Better Auth): protected resources of the old sign-in service.';
COMMENT ON TABLE "oauthConsent" IS 'Retired (Better Auth): consents granted in the old sign-in service.';
COMMENT ON TABLE "oauthAccessToken" IS 'Retired (Better Auth): access tokens issued by the old sign-in service.';
COMMENT ON TABLE "oauthRefreshToken" IS 'Retired (Better Auth): refresh tokens issued by the old sign-in service.';
